                        inline number cubicinterp(number a, number w, number x, number y, number z) {
                            number a1 = 1. + a;
                            number aa = a * a1;
                            number b = 1. - a;
                            number b1 = 2. - a;
                            number bb = b * b1;
                            number fw = -.1666667 * bb * a;
                            number fx = .5 * bb * a1;
                            number fy = .5 * aa * b1;
                            number fz = -.1666667 * aa * b;
                            return w * fw + x * fx + y * fy + z * fz;
                        }
                        
