                                number fb = this->allpass_tilde_06_feedBack_read(delayTimeinSamps, 0);
                                number ov = ff + (x[(Index)i] - fb) * (__gain * -1.0);
                                fixdenorm(ov);
                                this->allpass_tilde_06_feedForward_write(x[(Index)i]);
                                this->allpass_tilde_06_feedBack_write(ov);
