            void process(
                const SampleValue * const* inputs,
                Index numInputs,
                SampleValue * const* outputs,
                Index numOutputs,
                Index n
            ) {
                this->vs = n;
                this->updateTime(this->getEngine()->getCurrentTime(), (ENGINE*)nullptr, true);
                SampleValue * out1 = (numOutputs >= 1 && outputs[0] ? outputs[0] : this->dummyBuffer);
                const SampleValue * in1 = (numInputs >= 1 && inputs[0] ? inputs[0] : this->zeroBuffer);
                this->p_09_perform(in1, this->signals[0], n);
                this->p_11_perform(this->signals[0], this->signals[1], n);
                this->p_13_perform(this->signals[1], this->signals[0], n);
                this->p_15_perform(this->signals[0], this->signals[1], n);
                this->p_10_perform(this->signals[1], this->signals[0], n);
                this->p_12_perform(this->signals[0], this->signals[1], n);
                this->p_14_perform(this->signals[1], this->signals[0], n);
                this->p_16_perform(this->signals[0], out1, n);
                this->stackprotect_perform(n);
                this->audioProcessSampleCount += this->vs;
            }
            
            void prepareToProcess(number sampleRate, Index maxBlockSize, bool force) {
                RNBO_ASSERT(this->_isInitialized);
            
                if (this->maxvs < maxBlockSize || !this->didAllocateSignals) {
                    Index i;
            
                    for (i = 0; i < 2; i++) {
                        this->signals[i] = resizeSignal(this->signals[i], this->maxvs, maxBlockSize);
                    }
            
                    this->zeroBuffer = resizeSignal(this->zeroBuffer, this->maxvs, maxBlockSize);
                    this->dummyBuffer = resizeSignal(this->dummyBuffer, this->maxvs, maxBlockSize);
                    this->didAllocateSignals = true;
                }
            
                const bool sampleRateChanged = sampleRate != this->sr;
                const bool maxvsChanged = maxBlockSize != this->maxvs;
                const bool forceDSPSetup = sampleRateChanged || maxvsChanged || force;
            
                if (sampleRateChanged || maxvsChanged) {
                    this->vs = maxBlockSize;
                    this->maxvs = maxBlockSize;
                    this->sr = sampleRate;
                    this->invsr = 1 / sampleRate;
                }
            
                RNBO_UNUSED(forceDSPSetup);
                this->p_09->prepareToProcess(sampleRate, maxBlockSize, force);
                this->p_10->prepareToProcess(sampleRate, maxBlockSize, force);
                this->p_11->prepareToProcess(sampleRate, maxBlockSize, force);
                this->p_12->prepareToProcess(sampleRate, maxBlockSize, force);
                this->p_13->prepareToProcess(sampleRate, maxBlockSize, force);
                this->p_14->prepareToProcess(sampleRate, maxBlockSize, force);
                this->p_15->prepareToProcess(sampleRate, maxBlockSize, force);
                this->p_16->prepareToProcess(sampleRate, maxBlockSize, force);
            
                if (sampleRateChanged)
                    this->onSampleRateChanged(sampleRate);
            }
            
            number msToSamps(MillisecondTime ms, number sampleRate) {
                return ms * sampleRate * 0.001;
            }
            
            MillisecondTime sampsToMs(SampleIndex samps) {
                return samps * (this->invsr * 1000);
            }
            
