    ParameterIndex getParameterOffset(BaseInterface& subpatcher) const {
        if (addressOf(subpatcher) == addressOf(this->p_17))
            return 2;
    
        if (addressOf(subpatcher) == addressOf(this->p_18))
            return 2 + this->p_17->getNumParameters();
    
        return 0;
    }
    
