                            inc = (destinationValue - lastRampValue) / rampTimeInSamples;
                            lastRampEnd += rampTimeInSamples;
                            this->linetilde_01_activeRamps->push(destinationValue);
                            this->linetilde_01_activeRamps->push(inc);
