            void codebox_02_in1_set(number in1) {
                this->codebox_02_in1 = in1;
                number midiToQuant = this->codebox_02_in1;
                number transposeRoot = this->codebox_02_in2;
                number scaleRoot = 0;
                list scalaFile = this->codebox_02_in3;
                number delta = 0;
                number midiQuantized = midiToQuant;
            
                if (this->listlen(scalaFile) != 0) {
                    number transposeRootOctaveInSemitones = transposeRoot - this->safemod(transposeRoot, 12);
                    number octaveToQuantInSemitones = midiToQuant - this->safemod(midiToQuant, 12);
                    number octaveToQuantFreq = this->codebox_02_mtof_next(octaveToQuantInSemitones, 440);
                    number adjustedTransposeRootOctave = midiToQuant - this->safemod(transposeRoot, 12) - this->safemod(midiToQuant - this->safemod(transposeRoot, 12), 12);
                    number adjustedTransposeRoot = adjustedTransposeRootOctave + this->safemod(transposeRoot, 12);
                    number adjustedTransposeRootFreq = this->codebox_02_mtof_next(adjustedTransposeRoot, 440);
            
                    for (number idx = 1; idx < this->listlen(scalaFile); idx = idx + 2) {
                        number cents = 0;
            
                        if (scalaFile[(Index)(idx + 1)] != 0) {
                            number ratio = (scalaFile[(Index)(idx + 1)] == 0. ? 0. : scalaFile[(Index)idx] / scalaFile[(Index)(idx + 1)]);
                            number freq = adjustedTransposeRootFreq * ratio;
            
                            cents = 1200 * rnbo_log2(
                                (((octaveToQuantFreq == 0. ? 0. : freq / octaveToQuantFreq)) <= 0.0000000001 ? 0.0000000001 : (octaveToQuantFreq == 0. ? 0. : freq / octaveToQuantFreq))
                            );//#map:_###_obj_###_:32
                        } else {
                            cents = scalaFile[(Index)idx];//#map:_###_obj_###_:35
                        }//#map:_###_obj_###_:29
            
                        number newDelta = cents / (number)100 - this->safemod(midiToQuant, 12);
            
                        if (rnbo_abs(newDelta) < rnbo_abs(delta) || idx == 1) {
                            delta = cents / (number)100 - this->safemod(midiToQuant, 12);//#map:_###_obj_###_:44
                        }//#map:_###_obj_###_:43
            
                        midiQuantized = midiToQuant + delta;//#map:_###_obj_###_:46
                    }//#map:_###_obj_###_:25
                }//#map:pitchShifter2/pitchQuantizer/codebox_obj-7:10
            
                this->codebox_02_out1_set(midiQuantized);//#map:pitchShifter2/pitchQuantizer/codebox_obj-7:50
                this->codebox_02_out2_set(delta);//#map:pitchShifter2/pitchQuantizer/codebox_obj-7:51
            }
            
