            number ftom_03_innerFtoM_next(number frequency, number tuning) {
                if (frequency <= 0.0) {
                    return -999;
                }
            
                if (frequency == this->ftom_03_innerFtoM_lastInValue && tuning == this->ftom_03_innerFtoM_lastTuning) {
                    return this->ftom_03_innerFtoM_lastOutValue;
                }
            
                this->ftom_03_innerFtoM_lastInValue = frequency;
                this->ftom_03_innerFtoM_lastTuning = tuning;
                this->ftom_03_innerFtoM_lastOutValue = (frequency == 0 || tuning == 0 ? 0 : 69. + 17.31234050465299 * rnbo_log(frequency / tuning));
                return this->ftom_03_innerFtoM_lastOutValue;
            }
            
