                        inline number safemod(number f, number m) {
                            if (m != 0) {
                                Int f_trunc = (Int)(trunc(f));
                                Int m_trunc = (Int)(trunc(m));
                        
                                if (f == f_trunc && m == m_trunc) {
                                    f = f_trunc % m_trunc;
                                } else {
                                    if (m < 0) {
                                        m = -m;
                                    }
                        
                                    if (f >= m) {
                                        if (f >= m * 2.0) {
                                            number d = f / m;
                                            Int i = (Int)(trunc(d));
                                            d = d - i;
                                            f = d * m;
                                        } else {
                                            f -= m;
                                        }
                                    } else if (f <= -m) {
                                        if (f <= -m * 2.0) {
                                            number d = f / m;
                                            Int i = (Int)(trunc(d));
                                            d = d - i;
                                            f = d * m;
                                        } else {
                                            f += m;
                                        }
                                    }
                                }
                            } else {
                                f = 0.0;
                            }
                        
                            return f;
                        }
                        
