                        void allpass_tilde_24_perform(
                            const Sample * x,
                            number delayTime,
                            number gain,
                            SampleValue * out1,
                            Index n
                        ) {
                            RNBO_UNUSED(gain);
                            Index i;
                        
                            for (i = 0; i < (Index)n; i++) {
                                number __gain = 0;
                                auto delayTimeinSamps = this->mstosamps(delayTime);
                                delayTimeinSamps = (delayTimeinSamps > 44100 ? 44100 : (delayTimeinSamps < 0 ? 0 : delayTimeinSamps));
                                __gain = (__gain > 0.99 ? 0.99 : (__gain < 0 ? 0 : __gain));
                                number ff = this->allpass_tilde_24_feedForward_read(delayTimeinSamps, 0);
                                number fb = this->allpass_tilde_24_feedBack_read(delayTimeinSamps, 0);
                                number ov = ff + (x[(Index)i] - fb) * (__gain * -1.0);
                                fixdenorm(ov);
                                this->allpass_tilde_24_feedForward_write(x[(Index)i]);
                                this->allpass_tilde_24_feedBack_write(ov);
                                this->allpass_tilde_24_feedForward_step();
                                this->allpass_tilde_24_feedBack_step();
                                out1[(Index)i] = ov;
                            }
                        }
                        
                        void xfade_tilde_44_perform(
                            number pos,
                            const SampleValue * in1,
                            const SampleValue * in2,
                            SampleValue * out,
                            Index n
                        ) {
                            Index i;
                        
                            for (i = 0; i < (Index)n; i++) {
                                out[(Index)i] = in1[(Index)i] * this->xfade_tilde_44_func_next(pos, 0) + in2[(Index)i] * this->xfade_tilde_44_func_next(pos, 1);
                            }
                        }
                        
                        void stackprotect_perform(Index n) {
                            RNBO_UNUSED(n);
                            auto __stackprotect_count = this->stackprotect_count;
                            __stackprotect_count = 0;
                            this->stackprotect_count = __stackprotect_count;
                        }
                        
                        number xfade_tilde_44_func_next(number pos, Int channel) {
                            {
                                {
                                    number nchan_1 = 2 - 1;
                        
                                    {
                                        pos = pos * nchan_1;
                                    }
                        
                                    {
                                        if (pos > nchan_1)
                                            pos = nchan_1;
                                        else if (pos < 0)
                                            pos = 0;
                                    }
                        
                                    pos = pos - channel;
                        
                                    if (pos > -1 && pos < 1) {
                                        {
                                            {
                                                return this->safesqrt(1.0 - rnbo_abs(pos));
                                            }
                                        }
                                    } else {
                                        return 0;
                                    }
                                }
                            }
                        }
                        
